import * as THREE from 'three';

export const HologramShaderMaterial = {
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0x00d2ff) },
  },
  vertexShader: /* glsl */ `
    uniform float uTime;
    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);

      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPosition = worldPos.xyz;

      // Slight vertex displacement scan wave
      float wave = sin(worldPos.y * 10.0 + uTime * 4.0) * 0.02;
      worldPos.xyz += normal * wave;

      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: /* glsl */ `
    uniform float uTime;
    uniform vec3 uColor;

    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec2 vUv;

    void main() {
      vec3 viewDir = normalize(cameraPosition - vWorldPosition);

      // Fresnel Rim Light calculation
      float fresnel = pow(1.0 - max(dot(viewDir, vNormal), 0.0), 2.5);

      // Scanline effect across vertical height
      float scanline = sin(vWorldPosition.y * 40.0 - uTime * 8.0) * 0.5 + 0.5;
      scanline = pow(scanline, 2.0);

      // Grid lattice pattern
      float grid = step(0.92, fract(vUv.x * 30.0)) + step(0.92, fract(vUv.y * 30.0));

      vec3 glowColor = uColor * (fresnel * 2.5 + scanline * 0.4 + grid * 0.6);
      float alpha = clamp(fresnel * 0.8 + scanline * 0.3 + 0.1, 0.1, 0.9);

      gl_FragColor = vec4(glowColor, alpha);
    }
  `,
};

import * as THREE from 'three';

export const RoadGridShaderMaterial = {
  uniforms: {
    uTime: { value: 0 },
    uSpeed: { value: 1.0 },
    uColor: { value: new THREE.Color(0x1c69d2) },
    uMode: { value: 0 }, // 0: Comfort, 1: Sport, 2: M Track
  },
  vertexShader: /* glsl */ `
    varying vec2 vUv;
    varying vec3 vWorldPosition;

    void main() {
      vUv = uv;
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPosition = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: /* glsl */ `
    uniform float uTime;
    uniform float uSpeed;
    uniform vec3 uColor;
    uniform int uMode;

    varying vec2 vUv;
    varying vec3 vWorldPosition;

    void main() {
      vec2 uv = vWorldPosition.xz * 0.5;

      // Animate grid motion along Z axis
      uv.y += uTime * uSpeed * 3.0;

      // Anti-aliased Grid Lines
      vec2 gridUv = abs(fract(uv - 0.5) - 0.5) / fwidth(uv);
      float line = 1.0 - min(min(gridUv.x, gridUv.y), 1.0);

      // Speed streak lines along Z axis
      float streak = sin(vWorldPosition.z * 2.0 + uTime * uSpeed * 10.0) * 0.5 + 0.5;
      streak = pow(streak, 8.0) * step(0.95, fract(vWorldPosition.x * 0.8));

      // Distance radial fadeout (fade into horizon)
      float dist = length(vWorldPosition.xz);
      float fade = smoothstep(30.0, 5.0, dist);

      vec3 gridColor = uColor;
      if (uMode == 1) { // Sport
        gridColor = mix(vec3(0.9, 0.1, 0.1), vec3(1.0, 0.3, 0.0), sin(uTime * 4.0) * 0.5 + 0.5);
      } else if (uMode == 2) { // M Track
        gridColor = mix(vec3(0.0, 0.8, 1.0), vec3(0.9, 0.0, 0.3), fract(vWorldPosition.z * 0.1 + uTime));
      }

      vec3 finalColor = gridColor * (line * 0.8 + streak * 2.0);
      float alpha = (line * 0.6 + streak * 0.9) * fade;

      gl_FragColor = vec4(finalColor, alpha);
    }
  `,
};

import * as THREE from 'three';

export const HeadlightShaderMaterial = {
  uniforms: {
    uTime: { value: 0 },
    uColor: { value: new THREE.Color(0x88ccff) },
    uIntensity: { value: 1.0 },
  },
  vertexShader: /* glsl */ `
    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec2 vUv;

    void main() {
      vUv = uv;
      vNormal = normalize(normalMatrix * normal);
      vec4 worldPos = modelMatrix * vec4(position, 1.0);
      vWorldPosition = worldPos.xyz;
      gl_Position = projectionMatrix * viewMatrix * worldPos;
    }
  `,
  fragmentShader: /* glsl */ `
    uniform float uTime;
    uniform vec3 uColor;
    uniform float uIntensity;

    varying vec3 vNormal;
    varying vec3 vWorldPosition;
    varying vec2 vUv;

    void main() {
      // Cone length fade (from tip UV y=0 to base UV y=1)
      float lengthFade = smoothstep(0.0, 0.4, vUv.y) * smoothstep(1.0, 0.6, vUv.y);

      // Edge falloff based on normal facing angle to camera
      vec3 viewDir = normalize(cameraPosition - vWorldPosition);
      float edgeFade = pow(1.0 - abs(dot(viewDir, vNormal)), 2.0);

      // Subtle volumetric light dust flicker
      float flicker = sin(uTime * 15.0 + vWorldPosition.x * 10.0) * 0.05 + 0.95;

      vec3 beamColor = uColor * uIntensity * flicker * 2.0;
      float alpha = lengthFade * edgeFade * 0.4 * uIntensity;

      gl_FragColor = vec4(beamColor, alpha);
    }
  `,
};

import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { HologramShaderMaterial } from './Shaders/HologramShader';
import { HeadlightShaderMaterial } from './Shaders/HeadlightShader';

interface BmwCarModelProps {
  carColor: string;
  isXRay: boolean;
  headlightsOn: boolean;
  driveMode: 'comfort' | 'sport' | 'mtrack';
  isMoving?: boolean;
}

export const BmwCarModel: React.FC<BmwCarModelProps> = ({
  carColor,
  isXRay,
  headlightsOn,
  driveMode,
  isMoving = true,
}) => {
  const groupRef = useRef<THREE.Group>(null!);
  const wheelsGroupRef = useRef<THREE.Group>(null!);
  const hologramMatRef = useRef<THREE.ShaderMaterial>(null!);
  const headlightBeamMatRef = useRef<THREE.ShaderMaterial>(null!);

  // Custom Shader Materials
  const hologramShader = useMemo(() => {
    return new THREE.ShaderMaterial({
      ...HologramShaderMaterial,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
  }, []);

  const headlightShader = useMemo(() => {
    return new THREE.ShaderMaterial({
      ...HeadlightShaderMaterial,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
    });
  }, []);

  // Standard PBR Car Body Material
  const bodyMaterial = useMemo(() => {
    return new THREE.MeshPhysicalMaterial({
      color: new THREE.Color(carColor),
      metalness: 0.85,
      roughness: 0.15,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1,
      reflectivity: 0.9,
    });
  }, [carColor]);

  // Carbon Fiber Material
  const carbonMaterial = useMemo(() => {
    return new THREE.MeshStandardMaterial({
      color: 0x111115,
      roughness: 0.4,
      metalness: 0.6,
    });
  }, []);

  // Glass Material
  const glassMaterial = useMemo(() => {
    return new THREE.MeshPhysicalMaterial({
      color: 0x111827,
      metalness: 0.1,
      roughness: 0.05,
      transmission: 0.7,
      thickness: 0.5,
      transparent: true,
      opacity: 0.8,
    });
  }, []);

  // Emissive Kidney Grille Rim Color
  const grilleGlowColor = useMemo(() => {
    if (driveMode === 'sport') return '#ef4444';
    if (driveMode === 'mtrack') return '#00d2ff';
    return '#1c69d2';
  }, [driveMode]);

  // Animation Loop
  useFrame((state, delta) => {
    // Hologram shader uniform uTime
    if (hologramShader) {
      hologramShader.uniforms.uTime.value = state.clock.getElapsedTime();
    }
    if (headlightShader) {
      headlightShader.uniforms.uTime.value = state.clock.getElapsedTime();
      headlightShader.uniforms.uIntensity.value = headlightsOn ? 1.0 : 0.0;
    }

    // Wheel rotation simulation when moving
    if (isMoving && wheelsGroupRef.current) {
      const speed = driveMode === 'mtrack' ? 12 : driveMode === 'sport' ? 8 : 4;
      wheelsGroupRef.current.children.forEach((wheel) => {
        wheel.rotation.x += delta * speed;
      });
    }

    // Subtle chassis idle vibration
    if (groupRef.current) {
      groupRef.current.position.y = Math.sin(state.clock.getElapsedTime() * 4) * 0.01 + 0.35;
    }
  });

  return (
    <group ref={groupRef} position={[0, 0.35, 0]}>
      {/* ==================== CAR BODY SHELL ==================== */}
      {isXRay ? (
        // X-Ray Hologram Mesh
        <group>
          <mesh material={hologramShader}>
            <boxGeometry args={[2.1, 0.9, 4.6]} />
          </mesh>
          {/* Inner Battery Pack & Electric Drivetrain Core */}
          <mesh position={[0, -0.2, 0]}>
            <boxGeometry args={[1.6, 0.3, 2.5]} />
            <meshStandardMaterial color="#00ffff" emissive="#00aaaa" emissiveIntensity={0.8} wireframe />
          </mesh>
          <mesh position={[0, -0.1, 1.4]}>
            <cylinderGeometry args={[0.3, 0.3, 0.6, 16]} rotation={[0, 0, Math.PI / 2]} />
            <meshStandardMaterial color="#ff0055" emissive="#aa0033" emissiveIntensity={1.0} wireframe />
          </mesh>
        </group>
      ) : (
        // Detailed Solid Car Mesh
        <group>
          {/* Main Lower Cabin Chassis */}
          <mesh material={bodyMaterial} position={[0, 0.35, 0]} castShadow receiveShadow>
            <boxGeometry args={[2.0, 0.65, 4.4]} />
          </mesh>

          {/* Roof & Cockpit Cabin */}
          <mesh material={glassMaterial} position={[0, 0.85, -0.2]} castShadow>
            <boxGeometry args={[1.6, 0.55, 2.2]} />
          </mesh>

          {/* Roof Panel */}
          <mesh material={carbonMaterial} position={[0, 1.13, -0.2]} castShadow>
            <boxGeometry args={[1.5, 0.05, 1.8]} />
          </mesh>

          {/* Hood Power Dome Slope */}
          <mesh material={bodyMaterial} position={[0, 0.52, 1.4]} rotation={[0.12, 0, 0]} castShadow>
            <boxGeometry args={[1.9, 0.25, 1.6]} />
          </mesh>

          {/* Front Bumper & Carbon Fiber Splitter */}
          <mesh material={carbonMaterial} position={[0, 0.15, 2.22]} castShadow>
            <boxGeometry args={[2.05, 0.2, 0.3]} />
          </mesh>

          {/* Side Skirts */}
          <mesh material={carbonMaterial} position={[-1.02, 0.12, 0]} castShadow>
            <boxGeometry args={[0.1, 0.15, 3.8]} />
