import React, { useRef, useMemo } from 'react';
import { useFrame } from '@react-three/fiber';
import { ContactShadows, Environment } from '@react-three/drei';
import * as THREE from 'three';
import { RoadGridShaderMaterial } from './Shaders/RoadGridShader';

interface EnvironmentStudioProps {
  driveMode: 'comfort' | 'sport' | 'mtrack';
  isMoving?: boolean;
}

export const EnvironmentStudio: React.FC<EnvironmentStudioProps> = ({ driveMode, isMoving = true }) => {
  const roadMatRef = useRef<THREE.ShaderMaterial>(null!);

  // Mode based light colors
  const lightColors = useMemo(() => {
    if (driveMode === 'sport') {
      return {
        ambient: '#200505',
        key: '#ff3333',
        rim: '#ff6600',
        grid: new THREE.Color(0xef4444),
        modeInt: 1,
      };
    } else if (driveMode === 'mtrack') {
      return {
        ambient: '#031020',
        key: '#00d2ff',
        rim: '#ff0055',
        grid: new THREE.Color(0x00d2ff),
        modeInt: 2,
      };
    }
    return {
      ambient: '#090d16',
      key: '#ffffff',
      rim: '#1c69d2',
      grid: new THREE.Color(0x1c69d2),
      modeInt: 0,
    };
  }, [driveMode]);

  // Road Grid Shader Material
  const roadShader = useMemo(() => {
    return new THREE.ShaderMaterial({
      ...RoadGridShaderMaterial,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
    });
  }, []);

  useFrame((state, delta) => {
    if (roadShader) {
      roadShader.uniforms.uTime.value = state.clock.getElapsedTime();
      roadShader.uniforms.uSpeed.value = isMoving ? (driveMode === 'mtrack' ? 3.5 : driveMode === 'sport' ? 2.0 : 1.0) : 0.0;
      roadShader.uniforms.uColor.value = lightColors.grid;
      roadShader.uniforms.uMode.value = lightColors.modeInt;
    }
  });

  return (
    <group>
      {/* Dynamic Studio Ambient & Directional Lights */}
      <ambientLight intensity={0.6} color={lightColors.ambient} />

      {/* Primary Key Light with Soft Shadows */}
      <directionalLight
        position={[8, 12, 6]}
        intensity={2.0}
        color={lightColors.key}
        castShadow
        shadow-mapSize={2048}
        shadow-camera-near={0.5}
        shadow-camera-far={30}
        shadow-camera-left={-6}
        shadow-camera-right={6}
        shadow-camera-top={6}
        shadow-camera-bottom={-6}
      />

      {/* Secondary Fill & Rim Lights */}
      <directionalLight position={[-8, 6, -6]} intensity={1.5} color={lightColors.rim} />
      <pointLight position={[0, -0.5, 3]} intensity={1.2} color={lightColors.key} />

      {/* Realistic Contact Shadows Under Car */}
      <ContactShadows
        position={[0, 0, 0]}
        opacity={0.8}
        scale={12}
        blur={1.8}
        far={5}
        resolution={1024}
        color="#000000"
      />

      {/* Animated GLSL Cyber Road Grid Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, -0.01, 0]} material={roadShader}>
        <planeGeometry args={[80, 80, 1, 1]} />
      </mesh>

      {/* Realistic HDRI Environment Map Reflections */}
      <Environment preset="city" background={false} environmentIntensity={0.8} />
    </group>
  );
};

