import React, { useRef, Suspense } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Html } from '@react-three/drei';
import * as THREE from 'three';
import { BmwCarModel } from './BmwCarModel';
import { EnvironmentStudio } from './EnvironmentStudio';

interface Canvas3DProps {
  carColor: string;
  isXRay: boolean;
  headlightsOn: boolean;
  driveMode: 'comfort' | 'sport' | 'mtrack';
  cameraView: 'tour' | 'front' | 'rear' | 'wheel' | 'xray' | 'interior';
}

const CAMERA_POSITIONS: Record<string, [number, number, number]> = {
  tour: [5.0, 2.2, 6.5],
  front: [0, 1.2, 5.2],
  rear: [0, 1.2, -5.2],
  wheel: [-2.6, 0.7, 1.6],
  xray: [3.8, 2.6, 3.8],
  interior: [0, 1.15, 0.2],
};

const CAMERA_TARGETS: Record<string, [number, number, number]> = {
  tour: [0, 0.4, 0],
  front: [0, 0.5, 1.8],
  rear: [0, 0.5, -1.8],
  wheel: [-1.0, 0.35, 1.45],
  xray: [0, 0.3, 0],
  interior: [0, 0.6, -0.2],
};

// Sub-component to smoothly interpolate camera position & controls target
function CameraRig({ cameraView }: { cameraView: string }) {
  const controlsRef = useRef<any>(null!);

  useFrame((state, delta) => {
    const targetPos = CAMERA_POSITIONS[cameraView] || CAMERA_POSITIONS.tour;
    const targetLookAt = CAMERA_TARGETS[cameraView] || CAMERA_TARGETS.tour;

    // Smoothly lerp camera position
    state.camera.position.lerp(new THREE.Vector3(...targetPos), delta * 3);

    // Smoothly lerp controls target
    if (controlsRef.current) {
      controlsRef.current.target.lerp(new THREE.Vector3(...targetLookAt), delta * 3);
      controlsRef.current.update();
    }
  });

  return (
    <OrbitControls
      ref={controlsRef}
      makeDefault
      enableDamping
      dampingFactor={0.05}
      minDistance={2.0}
      maxDistance={14}
      maxPolarAngle={Math.PI / 2 + 0.05} // Don't go below floor
      autoRotate={cameraView === 'tour'}
      autoRotateSpeed={1.2}
    />
  );
}

