        <div className="text-center font-orbitron">
          <div className="text-sm font-bold text-cyan-300">LOADING BMW M4 3D MODEL</div>
          <div className="text-[10px] text-gray-400 font-mono mt-1">HIGH-POLY GLTF ASSET</div>
        </div>
      </div>
    </Html>
  );
}

export const Canvas3D: React.FC<Canvas3DProps> = ({
  carColor,
